action.command:
cat > /tmp/check.php <<'EOF'
<?php
echo 'geocoder.throttle: ' . (\Drupal::hasService('geocoder.throttle') ? 'yes' : 'no') . PHP_EOL;
echo 'addressLookup: ' . (\Drupal::hasService('openculturas_openstreetmap.addressLookup') ? 'yes' : 'no') . PHP_EOL;
$m = \Drupal::service('module_handler');
echo 'osm enabled: ' . ($m->moduleExists('openculturas_openstreetmap') ? 'yes' : 'no') . PHP_EOL;
echo 'map enabled: ' . ($m->moduleExists('openculturas_map') ? 'yes' : 'no') . PHP_EOL;
echo 'geocoder enabled: ' . ($m->moduleExists('geocoder') ? 'yes' : 'no') . PHP_EOL;
EOF
cd /workspace && cp /tmp/check.php /workspace/check_tmp.php && su ddevuser -c "ddev drush php:script check_tmp.php" 2>&1 | tail -8; rm -f /workspace/check_tmp.php

